import{_ as p,a0 as t,w as r,s as n,ao as l,I as i,x as s,a1 as d,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux 系統下查看硬件信息命令大全 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系統下查看硬件信息命令大全 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系統下查看硬件信息命令大全 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系統下查看硬件信息命令大全 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20160104 How to Check Hardware Information on Linux Using Command Line","title":"Linux 系統下查看硬件信息命令大全","tag":"201601","desc":""},"relativePath":"201601/20160104 How to Check Hardware Information on Linux Using Command Line.md","filePath":"[post].md"}'),c={name:"201601/20160104 How to Check Hardware Information on Linux Using Command Line.md"};function h(m,e,f,u,_,w){const a=t("Link");return r(),n("div",null,[e[13]||(e[13]=l(`<h1 id="linux-系統下查看硬件信息命令大全" tabindex="-1">Linux 系統下查看硬件信息命令大全 <a class="header-anchor" href="#linux-系統下查看硬件信息命令大全" aria-label="Permalink to “Linux 系統下查看硬件信息命令大全”">​</a></h1><p><img src="https://maketecheasier-holisticmedia.netdna-ssl.com/assets/uploads/2015/12/hdd_info_featured-1.png" alt=""></p><p>有許多命令可以用來查看 Linux 系統上的硬件信息。有些命令只能夠打印出像 CPU 和內存這一特定的硬件組件信息，另外一些命令可以查看多種硬件組件的信息。</p><p>這個教程可以帶大家快速瞭解一下查看各種硬件設備的信息和配置詳情的最常用的命令。</p><h3 id="lscpu" tabindex="-1">lscpu <a class="header-anchor" href="#lscpu" aria-label="Permalink to “lscpu”">​</a></h3><p><code>lscpu</code>命令能夠查看 CPU 和處理單元的信息。該命令沒有任何其他選項或者別的功能。</p><pre><code>lscpu
</code></pre><p>運行該命令會看到下面輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lscpu.png" alt="hdd_info_lscpu"></p><h3 id="lspci" tabindex="-1">lspci <a class="header-anchor" href="#lspci" aria-label="Permalink to “lspci”">​</a></h3><p><code>lspci</code>是另一個命令列工具，可以用來列出所有的 PCI 總線，還有與 PCI 總線相連的設備的詳細信息，比如 VGA 適配器、顯卡、網絡適配器、usb 端口、SATA 控制器等。</p><pre><code>lspci
</code></pre><p>你可以看到類似下圖的輸出信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lspci-1.png" alt="hdd_info_lspci"></p><p>可以通過運行下面的命令來過濾出特定設備的信息：</p><pre><code>lspci -v | grep &quot;VGA&quot; -A 12
</code></pre><p>運行上面的命令可以看到類似下圖的關於顯卡的信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lspci_vga.png" alt="hdd_info_lspci_vga"></p><h3 id="lshw" tabindex="-1">lshw <a class="header-anchor" href="#lshw" aria-label="Permalink to “lshw”">​</a></h3><p><code>lshw</code>是一個通用的工具，可以列出多種硬件單元的詳細或者概要的信息，比如 CPU、內存、usb 控制器、硬盤等。<code>lshw</code>能夠從各個“/proc”文件中提取出相關的信息。</p><pre><code>lshw -short
</code></pre><p>通過運行上面的命令可以看到下面的信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lshw.png" alt="hdd_info_lshw"></p><h3 id="lsscsi" tabindex="-1">lsscsi <a class="header-anchor" href="#lsscsi" aria-label="Permalink to “lsscsi”">​</a></h3><p>通過運行下面的命令可以列出像硬盤和光驅等 scsi/sata 設備的信息：</p><pre><code>lsscsi
</code></pre><p>會得到類似下面的輸出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lsscsi-1.png" alt="hdd_info_lsscsi"></p><h3 id="lsusb" tabindex="-1">lsusb <a class="header-anchor" href="#lsusb" aria-label="Permalink to “lsusb”">​</a></h3><p><code>lsusb</code>命令能夠列出 USB 控制器和與 USB 控制器相連的設備的詳細信息。默認情況下，<code>lsusb</code>命令只打印出概要信息。可以通過使用-v參數打印每一個usb端口的詳細信息。</p><pre><code>lsusb
</code></pre><p>可以看到下面輸出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_lsusb.png" alt="hdd_info_lsusb"></p><h3 id="inxi" tabindex="-1">Inxi <a class="header-anchor" href="#inxi" aria-label="Permalink to “Inxi”">​</a></h3><p><code>Inxi</code>是一個 bash 腳本，能夠從系統的多個來源和命令獲取硬件信息，並打印出一個非技術人員也能看懂的友好的報告。</p><p>默認情況下，Ubuntu 上沒有安裝<code>inxi</code>。可以通過運行下面命令來安裝<code>Inxi</code>：</p><pre><code>sudo apt-get install inxi
</code></pre><p>安裝完<code>Inxi</code>之後，通過運行下面命令能夠得到硬件相關的信息：</p><pre><code>inxi -Fx
</code></pre><p>能夠得到類似下圖的輸出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_inxi.jpg" alt="hdd_info_inxi"></p><h3 id="df" tabindex="-1">df <a class="header-anchor" href="#df" aria-label="Permalink to “df”">​</a></h3><p><code>df</code>命令能夠列出不同分區的概要信息、掛載點、已用的和可用的空間。</p><p>可以在使用<code>df</code>命令的時候加上<code>-H</code>參數。</p><pre><code>df -H
</code></pre><p>會得到下面的輸出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_df-1.png" alt="hdd_info_df"></p><h3 id="free" tabindex="-1">Free <a class="header-anchor" href="#free" aria-label="Permalink to “Free”">​</a></h3><p>通過使用<code>free</code>命令可以查看系統中使用的、閒置的和 RAM 的總體數量。</p><pre><code>free -m
</code></pre><p>會看到下面輸出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_free.png" alt="hdd_info_free"></p><h3 id="dmidecode" tabindex="-1">Dmidecode <a class="header-anchor" href="#dmidecode" aria-label="Permalink to “Dmidecode”">​</a></h3><p><code>dmidecode</code>命令與其他命令不同。該命令是從硬件中的 DMI 表中讀取信息的。</p><p>要查看處理器的信息，運行下面命令：</p><pre><code>sudo dmidecode -t processor
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_dmi_processor.jpg" alt="hdd_info_dmi_processor"></p><p>要查看內存的信息，運行下面命令：</p><pre><code>sudo dmidecode -t memory
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_dmi_memory.png" alt="hdd_info_dmi_memory"></p><p>要查看 bios 的信息，運行下面命令：</p><pre><code>sudo dmidecode -t bios
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_dmi_bios.png" alt="hdd_info_dmi_bios"></p><h3 id="hdparm" tabindex="-1">Hdparm <a class="header-anchor" href="#hdparm" aria-label="Permalink to “Hdparm”">​</a></h3><p><code>hdparm</code>命令可以用來顯示像硬盤這樣的 sata 設備的信息。</p><pre><code>sudo hdparm
</code></pre><p>可以看到下面的輸出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/hdd_info_hdparm.png" alt="hdd_info_hdparm"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>每個命令都有不同的方式來獲取硬件的信息。在查看特定的硬件信息的時候，可以嘗試使用不同的方式。上面所有的命令列工具在大部分的 Linux 發行版本中都是可以使用的，可以很容易的從倉庫中獲取安裝。</p><hr>`,71)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),d(a,{href:"https://www.maketecheasier.com/check-hardware-information-linux/"},{default:o(()=>[...e[0]||(e[0]=[s("https://www.maketecheasier.com/check-hardware-information-linux/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=s("作者：",-1)),d(a,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:o(()=>[...e[2]||(e[2]=[s("Hitesh Jethva",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),d(a,{href:"https://github.com/sonofelice"},{default:o(()=>[...e[3]||(e[3]=[s("sonofelice",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),d(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=s("本文由 ",-1)),d(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),d(a,{href:"https://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const k=p(c,[["render",h]]);export{g as __pageData,k as default};
